function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2 - 150 + 50 * Math.sin(t), H / 2 - 50, 20 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W / 2 + 100 + 50 * Math.cos(t), H / 2 - 150, 30 + 15 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // trees
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 50);
  ctx.lineTo(W / 2 - 100, H - 150 - 50 * Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H - 50);
  ctx.lineTo(W / 2 + 100, H - 150 - 50 * Math.cos(t));
  ctx.stroke();

  // birds
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W / 2 - 50 + 20 * Math.sin(t), H / 2 - 100);
  ctx.lineTo(W / 2 - 50 + 20 * Math.sin(t) + 10 * Math.cos(t), H / 2 - 90);
  ctx.lineTo(W / 2 - 50 + 20 * Math.sin(t) + 10 * Math.cos(t) - 10, H / 2 - 100);
  ctx.lineTo(W / 2 - 50 + 20 * Math.sin(t) - 10, H / 2 - 90);
  ctx.lineTo(W / 2 - 50 + 20 * Math.sin(t), H / 2 - 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2 + 50 + 20 * Math.cos(t), H / 2 - 150);
  ctx.lineTo(W / 2 + 50 + 20 * Math.cos(t) + 10 * Math.sin(t), H / 2 - 140);
  ctx.lineTo(W / 2 + 50 + 20 * Math.cos(t) + 10 * Math.sin(t) - 10, H / 2 - 150);
  ctx.lineTo(W / 2 + 50 + 20 * Math.cos(t) - 10, H / 2 - 140);
  ctx.lineTo(W / 2 + 50 + 20 * Math.cos(t), H / 2 - 150);
  ctx.stroke();

  ctx.restore();
}
